def encadrer_dizaines(n):
    dizaine_inf = (n // 10) * 10
    dizaine_sup = dizaine_inf + 10
    if n % 10 == 0:
        dizaine_sup = dizaine_inf
    return (dizaine_inf, dizaine_sup)

# Tests
print(encadrer_dizaines(47))   # (40, 50)
print(encadrer_dizaines(80))   # (80, 80)
print(encadrer_dizaines(123))  # (120, 130)
